// OST's text in Teams' app languages (Settings ▸ General ▸ Language and
// regional formats ▸ App language).
//
// The QML marks its text with qsTr(). i18n/ids.json (generated by
// i18n/l10n.py) keys each such string to the Teams string id it is. The
// catalogue of Teams' own translations, built on the device from Teams'
// string resources (api::teams_strings, cached in
// ~/.cache/ost/i18n/<locale>.json), maps each id to its text in Qt's form:
// %1, %2… for Teams' placeholders, %n for a count, and a plural message as
// {"=1": …, "one": …, "other": …}.
//
// Teams applies its app language at start (after Save and restart), sets
// the document direction from it (right to left for Arabic, Hebrew,
// Persian…) and formats with that culture; OST does the same with one
// translator installed before the QML loads, Qt's layout direction and the
// default QLocale.

#include <QtCore/QCoreApplication>
#include <QtCore/QFile>
#include <QtCore/QHash>
#include <QtCore/QJsonArray>
#include <QtCore/QJsonDocument>
#include <QtCore/QJsonObject>
#include <QtCore/QLocale>
#include <QtCore/QTranslator>
#include <QtCore/QTimer>
#include <QtCore/QUrl>
#include <QtQml/QQmlComponent>
#include <QtQml/QQmlContext>
#include <QtQml/QQmlEngine>
#include <QtQml/QQmlListReference>
#include <QtGui/QGuiApplication>
#include <QtGui/QWindow>
#include <QtQuick/QQuickItem>
#include <QtQuick/QQuickWindow>
#include <cstring>

namespace {

const QString kRoot = QStringLiteral(":/qt/qml/com/ost/desktop/i18n/");

// CLDR's cardinal plural categories for whole numbers, for Teams' string
// languages.
QString pluralCategory(const QString &lang, long long n)
{
    const long long m10 = n % 10, m100 = n % 100;
    auto in = [](long long v, long long a, long long b) { return v >= a && v <= b; };
    if (lang == u"ar") {
        if (n == 0) return QStringLiteral("zero");
        if (n == 1) return QStringLiteral("one");
        if (n == 2) return QStringLiteral("two");
        if (in(m100, 3, 10)) return QStringLiteral("few");
        if (in(m100, 11, 99)) return QStringLiteral("many");
        return QStringLiteral("other");
    }
    if (lang == u"cy") {
        switch (n) {
        case 0: return QStringLiteral("zero");
        case 1: return QStringLiteral("one");
        case 2: return QStringLiteral("two");
        case 3: return QStringLiteral("few");
        case 6: return QStringLiteral("many");
        default: return QStringLiteral("other");
        }
    }
    if (lang == u"he") {
        if (n == 1) return QStringLiteral("one");
        if (n == 2) return QStringLiteral("two");
        return QStringLiteral("other");
    }
    if (lang == u"ru" || lang == u"uk") {
        if (m10 == 1 && m100 != 11) return QStringLiteral("one");
        if (in(m10, 2, 4) && !in(m100, 12, 14)) return QStringLiteral("few");
        return QStringLiteral("many");
    }
    if (lang == u"bs" || lang == u"hr" || lang == u"sr") {
        if (m10 == 1 && m100 != 11) return QStringLiteral("one");
        if (in(m10, 2, 4) && !in(m100, 12, 14)) return QStringLiteral("few");
        return QStringLiteral("other");
    }
    if (lang == u"pl") {
        if (n == 1) return QStringLiteral("one");
        if (in(m10, 2, 4) && !in(m100, 12, 14)) return QStringLiteral("few");
        return QStringLiteral("many");
    }
    if (lang == u"cs" || lang == u"sk") {
        if (n == 1) return QStringLiteral("one");
        if (in(n, 2, 4)) return QStringLiteral("few");
        return QStringLiteral("other");
    }
    if (lang == u"lt") {
        if (m10 == 1 && !in(m100, 11, 19)) return QStringLiteral("one");
        if (in(m10, 2, 9) && !in(m100, 11, 19)) return QStringLiteral("few");
        return QStringLiteral("other");
    }
    if (lang == u"lv") {
        if (m10 == 0 || in(m100, 11, 19)) return QStringLiteral("zero");
        if (m10 == 1 && m100 != 11) return QStringLiteral("one");
        return QStringLiteral("other");
    }
    if (lang == u"ro") {
        if (n == 1) return QStringLiteral("one");
        if (n == 0 || in(m100, 2, 19)) return QStringLiteral("few");
        return QStringLiteral("other");
    }
    if (lang == u"sl") {
        if (m100 == 1) return QStringLiteral("one");
        if (m100 == 2) return QStringLiteral("two");
        if (in(m100, 3, 4)) return QStringLiteral("few");
        return QStringLiteral("other");
    }
    if (lang == u"mt") {
        if (n == 1) return QStringLiteral("one");
        if (n == 2) return QStringLiteral("two");
        if (n == 0 || in(m100, 3, 10)) return QStringLiteral("few");
        if (in(m100, 11, 19)) return QStringLiteral("many");
        return QStringLiteral("other");
    }
    if (lang == u"mk" || lang == u"is") {
        if (m10 == 1 && m100 != 11) return QStringLiteral("one");
        return QStringLiteral("other");
    }
    if (lang == u"fr" || lang == u"pt-br") {
        if (n == 0 || n == 1) return QStringLiteral("one");
        if (n != 0 && n % 1000000 == 0) return QStringLiteral("many");
        return QStringLiteral("other");
    }
    if (lang == u"es" || lang == u"it" || lang == u"ca" || lang == u"pt") {
        if (n == 1) return QStringLiteral("one");
        if (n != 0 && n % 1000000 == 0) return QStringLiteral("many");
        return QStringLiteral("other");
    }
    if (lang == u"hi" || lang == u"fa") {
        return (n == 0 || n == 1) ? QStringLiteral("one") : QStringLiteral("other");
    }
    if (lang == u"fil") {
        return (in(n, 1, 3) || (m10 != 4 && m10 != 6 && m10 != 9)) ? QStringLiteral("one") : QStringLiteral("other");
    }
    if (lang == u"ja" || lang == u"ko" || lang == u"zh" || lang == u"th" || lang == u"vi" || lang == u"id"
        || lang == u"ms" || lang == u"lo" || lang == u"km") {
        return QStringLiteral("other");
    }
    return n == 1 ? QStringLiteral("one") : QStringLiteral("other");
}

class Translator : public QTranslator
{
public:
    // `catalogue`: the catalogue built from Teams' resources (empty for
    // en-us: only OST's English plural forms then).
    bool load(const QString &catalogue, const QString &locale)
    {
        QFile ids(kRoot + QStringLiteral("ids.json"));
        if (!ids.open(QIODevice::ReadOnly))
            return false;
        QJsonObject strings;
        if (!catalogue.isEmpty()) {
            QFile cat(catalogue);
            if (!cat.open(QIODevice::ReadOnly))
                return false;
            strings = QJsonDocument::fromJson(cat.readAll()).object().value(QStringLiteral("strings")).toObject();
            if (strings.isEmpty())
                return false;
        }
        const QJsonArray keys = QJsonDocument::fromJson(ids.readAll()).array();
        m_rows.reserve(keys.size());
        for (qsizetype i = 0; i < keys.size(); ++i) {
            const QJsonArray k = keys[i].toArray();
            const QString source = k[0].toString(), dis = k[1].toString(), id = k[2].toString();
            // Teams' translation, else OST's English plural forms.
            m_rows.append(strings.contains(id) ? strings.value(id) : k.size() > 4 ? k[4] : QJsonValue());
            m_index.insert(key(source, dis), i);
            // the id names the string too: qsTr("…", "<ns>:<key>")
            m_index.insert(key(source, id), i);
        }
        const QString base = locale.section(QLatin1Char('-'), 0, 0);
        m_lang = base == u"pt" && locale == u"pt-br" ? QStringLiteral("pt-br") : base;
        m_locale = locale;
        return true;
    }

    bool isEmpty() const override { return m_index.isEmpty(); }

    QString translate(const char *, const char *sourceText, const char *disambiguation, int n) const override
    {
        if (!sourceText)
            return {};
        const QString source = QString::fromUtf8(sourceText);
        auto it = m_index.constFind(key(source, QString::fromUtf8(disambiguation ? disambiguation : "")));
        if (it == m_index.constEnd() && disambiguation && *disambiguation)
            it = m_index.constFind(key(source, QString()));
        if (it == m_index.constEnd())
            return {};
        const QJsonValue row = m_rows[*it];
        if (row.isString())
            return row.toString();
        if (row.isObject()) {
            const QJsonObject forms = row.toObject();
            const QString exact = QLatin1Char('=') + QString::number(n);
            if (forms.contains(exact))
                return forms[exact].toString();
            const QString cat = pluralCategory(m_lang, n < 0 ? -qint64(n) : n);
            if (forms.contains(cat))
                return forms[cat].toString();
            return forms[QStringLiteral("other")].toString();
        }
        return {};
    }

private:
    static QString key(const QString &source, const QString &dis) { return dis.isEmpty() ? source : source + QChar(4) + dis; }

    QHash<QString, qsizetype> m_index;
    QList<QJsonValue> m_rows;
    QString m_lang, m_locale;
};

// Right to left (Arabic, Hebrew, Persian), Teams' document is dir="rtl":
// its whole layout is the mirror image of the left-to-right one (every
// row, pane, margin and offset), while text and pictures read as
// themselves, each piece of text aligned to the start of its block (the
// right; English and names included), message bodies following their own
// direction (dir="auto"), and the icons its library marks flipInRtl drawn
// mirrored.
//
// OST does the same to each window: every top-level item of the window's
// content is mirrored about the window's centre line (a Scale of -1),
// and then each item that draws text, a picture, video or a web page is
// mirrored back about its own centre, so it reads normally where the
// mirrored layout puts it. Text left-aligned to its block becomes
// right-aligned (and right becomes left), unless the item sets
// `ostAutoDirection` (it follows its content). Pictures are mirrored back
// with Image.mirror, unless the item sets `ostMirrorsItself` (FluentIcon:
// it leaves Teams' flipInRtl icons mirrored). Items are found by sweeping
// the windows a few times a second; each is handled once.
class RtlLayout : public QObject
{
public:
    explicit RtlLayout(QObject *parent) : QObject(parent)
    {
        m_timer.setInterval(150);
        connect(&m_timer, &QTimer::timeout, this, &RtlLayout::sweep);
        m_timer.start();
    }

private:
    enum Kind { Other, Text, TextInput, TextEdit, Image, Opaque };

    void sweep()
    {
        for (QWindow *w : QGuiApplication::topLevelWindows()) {
            auto *qw = qobject_cast<QQuickWindow *>(w);
            if (!qw || !qw->isVisible())
                continue;
            QQuickItem *root = qw->contentItem();
            QQmlEngine *engine = nullptr;
            for (QQuickItem *c : root->childItems()) {
                if (!engine)
                    engine = qmlEngine(c);
            }
            if (!engine)
                continue;
            for (QQuickItem *c : root->childItems()) {
                if (c->property("_ostRtl").isNull()) {
                    c->setProperty("_ostRtl", true);
                    addScale(engine, c, root);
                }
                visit(engine, c);
            }
        }
    }

    void visit(QQmlEngine *engine, QQuickItem *item)
    {
        for (QQuickItem *c : item->childItems()) {
            const Kind k = kindOf(c->metaObject());
            if (c->property("_ostRtl").isNull()) {
                c->setProperty("_ostRtl", true);
                handle(engine, c, k);
            }
            if (k == Other || k == Image)
                visit(engine, c);
        }
    }

    void handle(QQmlEngine *engine, QQuickItem *c, Kind k)
    {
        const QVariant autoDir = c->property("ostAutoDirection");
        const bool followsContent = autoDir.isValid() && autoDir.toBool();
        switch (k) {
        case Text:
        case TextInput:
            if (!followsContent) {
                const int a = c->property("horizontalAlignment").toInt();
                const QString text = c->property("text").toString();
                if (a == Qt::AlignLeft)
                    c->setProperty("horizontalAlignment", int(Qt::AlignRight));
                else if (a == Qt::AlignRight && (text.isEmpty() || !text.isRightToLeft()))
                    c->setProperty("horizontalAlignment", int(Qt::AlignLeft));
            }
            addScale(engine, c, nullptr);
            break;
        case TextEdit:
        case Opaque:
            addScale(engine, c, nullptr);
            break;
        case Image: {
            const QVariant own = c->property("ostMirrorsItself");
            if (!(own.isValid() && own.toBool()))
                c->setProperty("mirror", !c->property("mirror").toBool());
            break;
        }
        case Other:
            break;
        }
    }

    // A Scale of -1 about `about`'s centre line (the window's) or the
    // item's own.
    void addScale(QQmlEngine *engine, QQuickItem *item, QQuickItem *about)
    {
        if (!m_scale || m_scale->engine() != engine) {
            delete m_scale;
            m_scale = new QQmlComponent(engine, this);
            m_scale->setData("import QtQuick\n"
                             "Scale { property Item t; property Item w; xScale: -1\n"
                             "  // the item's drawn centre: after its own scale about its transformOrigin\n"
                             "  readonly property real cx: !t ? 0 : t.width / 2 + (t.scale - 1) * ([Item.TopLeft, Item.Left, Item.BottomLeft].indexOf(t.transformOrigin) >= 0 ? t.width / 2 : [Item.TopRight, Item.Right, Item.BottomRight].indexOf(t.transformOrigin) >= 0 ? -t.width / 2 : 0)\n"
                             "  origin.x: !t ? 0 : w ? w.width / 2 - t.x : cx }\n",
                             QUrl());
        }
        QObject *s = m_scale->beginCreate(engine->rootContext());
        if (!s)
            return;
        s->setProperty("t", QVariant::fromValue(item));
        s->setProperty("w", QVariant::fromValue(about));
        m_scale->completeCreate();
        s->setParent(item);
        QQmlListReference(item, "transform").append(s);
    }

    // Qt Quick's item classes are private: known by name.
    static Kind kindOf(const QMetaObject *mo)
    {
        for (; mo; mo = mo->superClass()) {
            const char *n = mo->className();
            if (qstrcmp(n, "QQuickText") == 0)
                return Text;
            if (qstrcmp(n, "QQuickTextInput") == 0)
                return TextInput;
            if (qstrcmp(n, "QQuickTextEdit") == 0)
                return TextEdit;
            if (qstrcmp(n, "QQuickImage") == 0)
                return Image;
            if (qstrcmp(n, "QQuickPaintedItem") == 0 || qstrcmp(n, "QQuickCanvasItem") == 0 || qstrcmp(n, "QQuickVideoOutput") == 0
                || qstrcmp(n, "QQuickWebEngineView") == 0)
                return Opaque;
            if (qstrcmp(n, "QQuickItem") == 0)
                return Other;
        }
        return Other;
    }

    QTimer m_timer;
    QQmlComponent *m_scale = nullptr;
};

} // namespace

// Install OST's text in `locale` (one of Teams' string locales, "de-de"),
// its layout direction and its culture; before the QML loads. Whether the
// catalogue was found.
extern "C" bool ost_install_translator(const char *catalogue, const char *locale, const char *culture, bool rtl)
{
    const QString loc = QString::fromUtf8(locale);
    QLocale::setDefault(QLocale(QString::fromUtf8(culture)));
    QGuiApplication::setLayoutDirection(rtl ? Qt::RightToLeft : Qt::LeftToRight);
    if (rtl)
        new RtlLayout(QCoreApplication::instance());
    auto *t = new Translator;
    if (!t->load(QString::fromUtf8(catalogue), loc)) {
        delete t;
        return false;
    }
    t->setParent(QCoreApplication::instance());
    return QCoreApplication::installTranslator(t);
}

// OST's text for Rust code (the engine's and the backend's strings):
// QCoreApplication::translate, as qsTr in QML. Writes UTF-8 to `out` and
// returns its length (0 if it didn't fit).
extern "C" size_t ost_translate(const char *source, const char *disambiguation, int n, char *out, size_t cap)
{
    const QByteArray b = QCoreApplication::translate("ost", source, disambiguation, n).toUtf8();
    if (size_t(b.size()) >= cap)
        return 0;
    memcpy(out, b.constData(), size_t(b.size()));
    return size_t(b.size());
}
